<?php
require '/wordpress/wp-load.php';wp_set_current_user(1);
function seo_test($ok,$message){if(!$ok)throw new Exception($message);}
$s=qrp_sanitize_settings(['seo_title'=>'Pelplin & historie','seo_description'=>'Opis portalu','seo_verification'=>'abc"><script>x</script>','seo_enabled'=>true,'seo_schema'=>true,'seo_index'=>true]);seo_test(!str_contains($s['seo_verification'],'<'),'Verification token sanitized');update_option('qrp_settings',$s);update_option('blog_public',1);
$id=wp_insert_post(['post_type'=>'qrp_item','post_status'=>'publish','post_title'=>'Historia Pelplina','post_excerpt'=>'Krótki opis']);update_post_meta($id,'qrp_seo_title','Tytuł <test>');update_post_meta($id,'qrp_seo_description','Opis & szczegóły');global $wp_query;$wp_query=new WP_Query(['post_type'=>'qrp_item','p'=>$id]);$data=qrp_seo_data();seo_test($data['description']==='Opis & szczegóły','Entry description overrides excerpt');seo_test($data['url']===get_permalink($id),'Canonical uses entry permalink');seo_test(!$data['noindex'],'Published entry indexable');ob_start();do_action('wp_head');$html=ob_get_clean();seo_test(str_contains($html,'name="description"'),'Description emitted');seo_test(str_contains($html,'property="og:title"'),'Open Graph emitted');seo_test(str_contains($html,'application/ld+json'),'Structured data emitted');seo_test(str_contains($html,'Opis &amp; szczegóły'),'Attribute escaping preserved');
update_post_meta($id,'qrp_seo_noindex',1);seo_test(qrp_seo_data()['noindex'],'Per-entry noindex applied');$robots=apply_filters('wp_robots',[]);seo_test(!empty($robots['noindex']),'Robots meta noindex follows entry setting');$args=apply_filters('wp_sitemaps_posts_query_args',['post_type'=>'qrp_item','post_status'=>'publish','posts_per_page'=>100],'qrp_item');$q=new WP_Query($args);seo_test(!in_array($id,wp_list_pluck($q->posts,'ID')),'Noindex entry excluded from sitemap');
update_post_meta($id,'qrp_seo_noindex',0);$s['seo_index']=false;update_option('qrp_settings',$s);seo_test(qrp_seo_data()['noindex'],'Global portal noindex applied');$types=apply_filters('wp_sitemaps_post_types',['qrp_item'=>get_post_type_object('qrp_item')]);seo_test(!isset($types['qrp_item']),'Disabled portal omitted from sitemap');define('WPSEO_VERSION','test');seo_test(!qrp_seo_active(),'External SEO prevents duplicate metadata');echo 'SEO TESTS PASSED';
